mrb_value mrb_io_init_copy(mrb_state *mrb, mrb_value copy) {
  mrb_value orig;
  struct mrb_io *io, *orig_io;
  int oflags;

  orig = mrb_get_args(mrb, "o", &orig);

  if (!mrb_io_p(copy)) {
    mrb_raise(mrb, E_TYPE_ERROR, "wrong argument type (expected IO)");
  }

  if (!mrb_io_p(orig)) {
    mrb_raise(mrb, E_TYPE_ERROR, "wrong argument type (expected IO)");
  }

  io = (struct mrb_io *)mrb_data_get_ptr(mrb, copy, &mrb_io_type);
  orig_io = (struct mrb_io *)mrb_data_get_ptr(mrb, orig, &mrb_io_type);

  if (io->fd != -1) {
    mrb_io_close(mrb, copy);
  }

  io->fd = dup(orig_io->fd);
  if (io->fd == -1) {
    mrb_sys_fail(mrb, "dup");
  }

  fcntl(io->fd, F_SETFD, FD_CLOEXEC);

  oflags = fcntl(orig_io->fd, F_GETFL, 0);
  if (oflags == -1) {
    mrb_sys_fail(mrb, "F_GETFL");
  }

  if (fcntl(io->fd, F_SETFL, oflags) == -1) {
    mrb_sys_fail(mrb, "F_SETFL");
  }

  io->readable = orig_io->readable;
  io->writable = orig_io->writable;
  io->sync = orig_io->sync;

  return copy;
}
